"""Tests of navera_lite/camera.py (mission 18 part). Written for the course; it is not NAVERA code."""
import math

import numpy as np

from navera_lite.camera import (K_from_hfov, backproject_ground, camera_rotation, camera_rotation_hpr, focal_px,
                                footprint, gsd, nadir_homography, off_nadir_deg, project, tilt_position_error,
                                warp_point)

K = K_from_hfov(90.0, 960, 540)


def test_focal_and_K():
    assert abs(focal_px(90.0, 960) - 480.0) < 1e-9
    assert np.allclose(K, [[480, 0, 480], [0, 480, 270], [0, 0, 1]])


def test_level_camera_axes():
    assert np.allclose(camera_rotation_hpr(0.0), [[1, 0, 0], [0, -1, 0], [0, 0, -1]], atol=1e-12)
    q_north = (0.0, 0.0, math.sin(math.pi / 4), math.cos(math.pi / 4))      # yaw +90°: nose north
    assert np.allclose(camera_rotation(q_north), camera_rotation_hpr(0.0), atol=1e-12)
    assert abs(off_nadir_deg(camera_rotation_hpr(30.0, -12.0, 0.0)) - 12.0) < 1e-9


def test_project_backproject_round_trip():
    R = camera_rotation_hpr(40.0, -14.0, 5.0)
    C = [12.0, -7.0, 170.0]
    for X in ([0.0, 0.0, 0.0], [-18.0, -66.0, 0.0], [30.0, 20.0, 0.0]):
        uv = project(K, R, C, X)
        assert np.allclose(backproject_ground(K, R, C, *uv), X[:2], atol=1e-9)
    assert project(K, R, C, [0.0, 0.0, 400.0]) is None


def test_nose_down_looks_behind():
    g = backproject_ground(K, camera_rotation_hpr(0.0, -20.0, 0.0), [0.0, 0.0, 150.0], 480, 270)
    assert abs(g[1] + 150.0 * math.tan(math.radians(20.0))) < 1e-9
    assert backproject_ground(K, camera_rotation_hpr(0.0, 80.0, 0.0), [0.0, 0.0, 100.0], 480, 0) is None


def test_gsd_footprint_tilt():
    assert abs(gsd(100.0, 90.0, 960) - 100.0 / 480.0) < 1e-12
    assert np.allclose(footprint(K, camera_rotation_hpr(0.0), [0, 0, 100], 960, 540),
                       [[-100, 56.25], [100, 56.25], [100, -56.25], [-100, -56.25]])
    assert abs(tilt_position_error(100.0, 0.0, 1.0) - 100.0 * math.tan(math.radians(1.0))) < 1e-12


def test_homography_brings_nadir_to_centre():
    R = camera_rotation_hpr(40.0, -14.0, 5.0)
    H = nadir_homography(K, R, camera_rotation_hpr(0.0))
    under = project(K, R, [0.0, 0.0, 170.0], [0.0, 0.0, 0.0])
    assert np.allclose(warp_point(H, *under), (480.0, 270.0), atol=1e-9)
    assert np.allclose(nadir_homography(K, R, R), np.eye(3), atol=1e-12)
